parameters.command:
python3 - <<'PYEOF'
import json

# Load the current flow
with open('BellevueWeather.flow') as f:
    flow = json.load(f)

# Load definitions from registry
script_def = json.load(open('/tmp/def-script.json'))['Data']['Node']
decision_def = json.load(open('/tmp/def-decision.json'))['Data']['Node']
end_def = json.load(open('/tmp/def-end.json'))['Data']['Node']

# ---- New user-owned nodes ----
new_nodes = [
    {
        "id": "formatWeather1",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": { "label": "Format Weather Summary" },
        "inputs": {
            "script": (
                "const body = $vars.getBellevueWeather1.output.body;\n"
                "const temp = body.current.temperature_2m;\n"
                "const unit = (body.current_units && body.current_units.temperature_2m) ? body.current_units.temperature_2m : '\\u00b0F';\n"
                "return { temperature: temp, unit: unit, summaryText: 'Current temperature in Bellevue, WA: ' + temp + unit };"
            )
        }
    },
    {
        "id": "checkTemp1",
        "type": "core.logic.decision",
        "typeVersion": "1.1",
        "display": { "label": "Temp > 60°F?" },
        "inputs": {
            "expression": "$vars.formatWeather1.output.temperature > 60"
        }
    },
    {
        "id": "endNiceDay",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": { "label": "Nice Day" },
        "inputs": {},
        "outputs": {
            "summary": {
                "source": "=js:{ message: 'nice day', temperature: $vars.formatWeather1.output.temperature, unit: $vars.formatWeather1.output.unit, summaryText: $vars.formatWeather1.output.summaryText }"
            }
        }
    },
    {
        "id": "endJacket",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": { "label": "Bring a Jacket" },
        "inputs": {},
        "outputs": {
            "summary": {
                "source": "=js:{ message: 'bring a jacket', temperature: $vars.formatWeather1.output.temperature, unit: $vars.formatWeather1.output.unit, summaryText: $vars.formatWeather1.output.summaryText }"
            }
        }
    }
]

# Append to existing nodes
flow['nodes'] = flow['nodes'] + new_nodes

# ---- New definitions (script, decision, end) ----
flow['definitions'] = flow['definitions'] + [script_def, decision_def, end_def]

# ---- Edges ----
flow['edges'] = [
    {
        "id": "e-start-getBellevueWeather1",
        "sourceNodeId": "start",
        "sourcePort": "output",
        "targetNodeId": "getBellevueWeather1",
        "targetPort": "input"
    },
    {
        "id": "e-getBellevueWeather1-formatWeather1",
        "sourceNodeId": "getBellevueWeather1",
        "sourcePort": "default",
        "targetNodeId": "formatWeather1",
        "targetPort": "input"
    },
    {
        "id": "e-formatWeather1-checkTemp1",
        "sourceNodeId": "formatWeather1",
        "sourcePort": "success",
        "targetNodeId": "checkTemp1",
        "targetPort": "input"
    },
    {
        "id": "e-checkTemp1-endNiceDay",
        "sourceNodeId": "checkTemp1",
        "sourcePort": "true",
        "targetNodeId": "endNiceDay",
        "targetPort": "input"
    },
    {
        "id": "e-checkTemp1-endJacket",
        "sourceNodeId": "checkTemp1",
        "sourcePort": "false",
        "targetNodeId": "endJacket",
        "targetPort": "input"
    }
]

# ---- Variables: add globals ----
if 'variables' not in flow:
    flow['variables'] = {}
flow['variables']['globals'] = [
    {
        "id": "summary",
        "direction": "out",
        "type": "object",
        "description": "Weather summary with message field"
    }
]

# ---- Layout: add placeholder entries ----
for nid in ['formatWeather1', 'checkTemp1', 'endNiceDay', 'endJacket']:
    flow['layout']['nodes'][nid] = {
        "position": { "x": 0, "y": 0 },
        "size": { "width": 96, "height": 96 },
        "collapsed": False
    }

# Write out
with open('BellevueWeather.flow', 'w') as f:
    json.dump(flow, f, indent=2)

print("Flow written successfully")
print("Nodes:", [n['id'] for n in flow['nodes']])
print("Edges:", [e['id'] for e in flow['edges']])
print("Definitions:", [d['nodeType'] for d in flow['definitions']])
print("Globals:", [g['id'] for g in flow['variables'].get('globals', [])])
PYEOF

